{
  "outcome": "escalate",
  "rationale": "We are escalating this claim because an automated fraud flag was raised for an inflated estimate. Section 7.3 governs this finding by requiring escalation when the claimed amount is substantially higher than the usual repair cost, which is the case here.",
  "citations": [
    {
      "clause_id": "PLUS-7.3",
      "quote": "If the amount claimed is substantially higher than the usual cost of repairing the damage described, or is not supported by the itemized estimate, the claim must be escalated for review."
    }
  ]
}
